const taboo25Text={
 '01050':'Fast. Play only during your turn. Disengage from each enemy engaged with you and move to a connecting location with no enemies.'
};

const optionalRulesVersion=1;

function validOptionalRules(settings){
 return settings===undefined||(settings?.version===optionalRulesVersion&&Array.isArray(settings.active)&&
  settings.active.length===new Set(settings.active).size&&
  settings.active.every(rule=>Object.hasOwn(optionalRules,rule)));
}

const soloSeat='seat-1';
const leadCommands=new Set(['selectDifficulty','selectStoryLanguage','toggleOptionalRule','selectInvestigator','continueStory',
 'nextChapter','chooseLita','upgrade']);
const decisionCommands=new Set(['mulligan','resolveEncounter','choose','fast','closeWindow','commit','boost','reveal','continue']);

function commandActor(state,type){
 if(leadCommands.has(type))return state.leadActor??soloSeat;
 if(decisionCommands.has(type))return state.pending?.actor??state.turnActor??soloSeat;
 return state.turnActor??soloSeat;
}

function authorizeCommandActor(state,type,actor){
 const expected=commandActor(state,type);
 if(actor!==expected&&(actor!==undefined||expected!==soloSeat)){
  throw Error('Lệnh này thuộc ghế '+expected+'.');
 }
}

const reserved=new Set(['__proto__','constructor','prototype','toString','valueOf','hasOwnProperty']);
const identifier=value=>typeof value==='string'&&/^[a-zA-Z0-9_+-]{1,48}$/.test(value)&&!reserved.has(value);
const cardCode=value=>typeof value==='string'&&/^[0-9]{5}[a-z]?$/.test(value);
const index=value=>Number.isSafeInteger(value)&&value>=0;
const validators={
 add:cardCode,asset:identifier,code:cardCode,
 deck:value=>Array.isArray(value)&&value.length===30&&value.every(cardCode),
 difficulty:value=>['Easy','Standard','Hard','Expert'].includes(value),
 discardKnife:value=>typeof value==='boolean',
 index,indices:value=>Array.isArray(value)&&value.length<=6&&value.every(index),
 kind:identifier,language:value=>['vi','en'].includes(value),
 recruit:value=>typeof value==='boolean',remove:value=>value===null||cardCode(value),
 rule:identifier,skill:value=>['willpower','intellect','combat','agility'].includes(value),
 stat:value=>['hp','horror'].includes(value),target:identifier,to:identifier,token:identifier,
 tool:identifier,track:value=>['act','agenda'].includes(value),weapon:identifier,
 from:identifier,phase:value=>['enemy','upkeep','mythos'].includes(value),
 tokens:value=>Array.isArray(value)&&value.length>=1&&value.length<=40&&value.every(identifier),
 point:value=>['before-enemy-attacks','after-enemy-attacks','after-encounter'].includes(value)
};
const actions={
 skidsAction:[],hospitalDebts:[],child:[],end:[],advance:[],resource:[],draw:[],parley:[],resign:[],
 move:['to'],investigate:['tool?'],fight:['target','weapon?','discardKnife?'],evade:['target'],
 engage:['target'],play:['index'],heal:['asset','stat'],cop:['asset','target'],
 cultist:[],interrogate:['target'],disrupt:['skill'],sacrifice:[],unlock:['skill'],
 dreams:[],clearMadness:['code'],location:['stat?'],badge:[],supply:['index','asset?']
};
const portableCommandShapes={
 adminAdvance:['track'],adminToggle:[],boost:[],choose:['index'],chooseLita:['recruit'],
 closeWindow:[],commit:['index'],continue:[],continueStory:[],mulligan:['indices?'],
 nextChapter:[],resolveEncounter:[],reveal:[],selectDifficulty:['difficulty'],
 selectInvestigator:['code','deck?'],selectStoryLanguage:['language'],toggleOptionalRule:['rule'],
 upgrade:['add','remove?']
};

function matches(args,fields){
 const keys=new Set(fields.map(field=>field.replace(/\?$/,'')));
 return fields.every(field=>field.endsWith('?')||Object.hasOwn(args,field))&&
  Object.entries(args).every(([key,value])=>keys.has(key)&&validators[key](value));
}

function validPortableCommand(type,args){
 if(!args||typeof args!=='object'||Array.isArray(args))return false;
 if(type==='action'||type==='fast'){
  if(!Object.hasOwn(actions,args.kind)||
     (type==='fast'&&!['play','hospitalDebts','badge','cop','child'].includes(args.kind)))return false;
  if(args.kind==='fight'&&args.discardKnife!==undefined&&!args.weapon)return false;
  return matches(args,['kind',...actions[args.kind]]);
 }
 return Object.hasOwn(portableCommandShapes,type)&&matches(args,portableCommandShapes[type]);
}

const sandboxEditShapes={
 move:['from','to','index'],bag:['tokens'],phase:['phase'],window:['point']
};

function validDebugCommand(type,args){
 if(validPortableCommand(type,args))return true;
 if(!args||typeof args!=='object'||Array.isArray(args))return false;
 if(type==='noop')return matches(args,[]);
 if(type==='reveal')return matches(args,['token']);
 return type==='sandboxEdit'&&Object.hasOwn(sandboxEditShapes,args.kind)&&
  matches(args,['kind',...sandboxEditShapes[args.kind]]);
}

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const command=(kind,args={})=>`data-command="${kind}" data-args="${esc(JSON.stringify(args))}"`;
const localTextFaces={'01022':'Evidence!','01023':'Dodge','01086':'Knife','02158':'Charisma','05313':'Hallowed Mirror','05314':'Soothing Melody',
 '05316':'Occult Lexicon','05317':'Blood-Rite','53002':'Survival Knife','01050':'Elusive'};
function hasLocalTextFace(code){return Object.hasOwn(localTextFaces,code);}
const img=(code,alt='',cls='')=>hasLocalTextFace(code)
 ?`<span class="card-text-face ${esc(cls)}">${esc(alt||localTextFaces[code])}</span>`
 :`<img class="${cls}" src="${ART[code]}" alt="${esc(alt)}" loading="lazy">`;
const inspect=(code,label='')=>`data-inspect="${esc(code)}" aria-label="Xem ${esc(label||code)}"`;
const art=name=>SCENE_ART[name];

function handPlayOption(engine,index) {
 const s=engine.s,code=s.hand[index],card=engine.card(code);
 if(!['asset','event'].includes(card.type_code))return null;
 const cost=engine.playCost(code),fast=engine.isFastCard(code),reload=code==='01026';
 return {label:card.name,cost,fast,args:{kind:reload?'supply':'play',index},
  disabled:Boolean(['01010','01022','01023'].includes(code)||engine.isScreamedAlly(code)||s.voices||s.resources<cost||(reload&&!engine.firearms().length)||
   (code==='05314'&&!engine.canPlayMelody())||(code==='01050'&&!engine.canPlayElusive())||(!s.actions&&!fast))};
}

function actorMeter(symbol,label,current,max,style){
 const remaining=Math.max(0,max-current);
 return `<span class="actor-meter ${style}" aria-label="${label}: ${remaining}/${max}"><span aria-hidden="true">${symbol}</span><span class="actor-meter-track"><i style="width:${max>0?100*remaining/max:0}%"></i></span><b>${remaining}/${max}</b></span>`;
}
function actorHud(engine,code,state){
 const c=engine.card(code);
 const meter=(type,current,max)=>actorMeter(type==='hp'?'♥':'◈',type==='hp'?'Sức khỏe':'Tinh thần',current,max,type);
 let stats;
 if(c.type_code==='enemy'){
  const values=[['⚔','Độ khó đánh',engine.enemyDifficulty(state,'fight')],['➶','Độ khó né',engine.enemyDifficulty(state,'evade')],['♥','Damage gây ra',c.enemy_damage??0],['◈','Horror gây ra',c.enemy_horror??0]];
  if(state.doom)values.push(['◆','Doom',state.doom]);
  stats=meter('hp',state.damage,engine.enemyHealth(state))+`<span class="actor-stats">${values.map(([icon,label,n])=>`<span title="${label}: ${n}" aria-label="${label}: ${n}">${icon}${n}</span>`).join('')}</span>`;
 }else if(c.type_code==='investigator'){
  stats=meter('hp',engine.s.hp,engine.healthLimit())+meter('horror',engine.s.horror,engine.sanityLimit());
 }else{
  stats=(c.health?meter('hp',state?.hp??0,c.health):'')+(c.sanity?meter('horror',state?.horror??0,c.sanity):'');
 }
 return stats?`<span class="actor-hud">${stats}</span>`:'';
}

