function canonicalPrinting(code){
 return typeof code==='string'&&Object.hasOwn(alternatePrintings,code)?alternatePrintings[code].canonical:code;
}

function checkDeckCopyLimit(card,count){
 const limit=card.deck_limit??2;
 if(count>limit)throw Error(limit===2?'Tối đa hai bản cùng tên: '+card.name:'Giới hạn '+limit+' bản: '+card.name);
}

function startingDeckPool(investigator){
 if(typeof investigator!=='string'||!Object.hasOwn(INVESTIGATORS,investigator))throw Error('Điều tra viên chưa được hỗ trợ.');
 const extra=investigator==='01001'?['05316']:['01050'];
 return [...INVESTIGATORS[investigator].deck,'01022','01023','01086','05313',...extra];
}

function validateStartingDeck(cards,investigator,deck){
 const pool=new Set(startingDeckPool(investigator));
 if(!Array.isArray(deck)||deck.length!==30)throw Error('Deck cần đúng 30 lá thường.');
 const names=new Map();
 for(const code of deck){
  if(!pool.has(code)||!Object.hasOwn(cards,code)){
   throw Error('Lá chưa được hỗ trợ trong deck này: '+String(code));
  }
  const card=cards[code],{name}=card;
  const count=(names.get(name)??0)+1;
  checkDeckCopyLimit(card,count);
  names.set(name,count);
 }
 return [...deck];
}

function quoteDeckUpgrade(cards,investigator,campaign,add,remove){
 const card=Object.hasOwn(cards,add)?cards[add]:null;
 if(!campaign||!card||!Number.isInteger(card.xp)||card.xp<=0)throw Error('Nâng cấp không hợp lệ.');
 const deck=campaign.deck;
 const copies=deck.filter(code=>cards[code]?.name===card.name).length;
 if(card.permanent){
  if(remove!=null||campaign.xp<card.xp)throw Error('Không thể mua Permanent: kiểm tra XP và lá thay.');
  checkDeckCopyLimit(card,copies+1);
  return {cost:card.xp,index:null};
 }
 const index=deck.indexOf(remove);
 const old=index>=0?cards[remove]:null;
 const def=INVESTIGATORS[investigator];
 if(!old||old.permanent||[def.signature,def.weakness,'01097','01117',...MADNESS].includes(remove)){
  throw Error('Không thể thay lá này.');
 }
 const sameName=card.name===old.name;
 const cost=sameName?card.xp-(old.xp??0):card.xp;
 if(cost<=0||campaign.xp<cost)throw Error('Không đủ XP hoặc level nâng cấp không hợp lệ.');
 checkDeckCopyLimit(card,copies+1-Number(sameName));
 return {cost,index};
}

function readDeckFile(data){
 if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Tệp deck không hợp lệ.');
 const investigator=canonicalPrinting(data.investigator_code);
 if(typeof investigator!=='string'||!Object.hasOwn(INVESTIGATORS,investigator))throw Error('Điều tra viên chưa được hỗ trợ.');
 if(typeof data.name!=='string'||!data.name.trim()||data.name.length>100||
    !data.slots||typeof data.slots!=='object'||Array.isArray(data.slots)){
  throw Error('Tệp deck thiếu tên hoặc danh sách lá.');
 }
 const entries=Object.entries(data.slots);
 if(entries.length>100||entries.some(([code,n])=>!/^[0-9]{5}[a-z]?$/.test(code)||!Number.isInteger(n)||n<0||n>30)){
  throw Error('Mã hoặc số lượng lá không hợp lệ.');
 }
 const def=INVESTIGATORS[investigator];
 const required=new Set([def.signature,def.weakness,'01097','01000']);
 const deck=entries.map(([code,count])=>[canonicalPrinting(code),count])
  .filter(([code])=>!required.has(code)).flatMap(([code,n])=>Array(n).fill(code));
 if(deck.length>100)throw Error('Tệp deck có quá nhiều lá.');
 return {name:data.name.trim(),investigator,deck};
}

function writeDeckFile(draft){
 const slots={};
 for(const code of draft.deck)slots[code]=(slots[code]??0)+1;
 return {name:draft.name,investigator_code:draft.investigator,slots};
}

const remoteDeckAvailable=false;
function loadRemoteDeck(){throw Error('Offline build');}



function starterDraft(cards,investigator){
 const {deck}=INVESTIGATORS[investigator];
 return {name:cards[investigator].name,investigator,deck:[...deck,...deck]};
}

function deckEditorView(engine,drafts,draft,error='',remoteAvailable=false){
 const entries=Object.keys(INVESTIGATORS).map(code=>
  `<button type="button" data-deck-new="${code}">Deck mới · ${esc(engine.cards[code].name)}</button>`).join('');
 const saved=drafts.map((item,index)=>
  `<button type="button" data-deck-open="${index}">${esc(item.name)} · ${esc(engine.cards[item.investigator].name)}</button>`).join('');
 let editor='';
 if(draft){
  const {slots}=writeDeckFile(draft);
  const pool=[...new Set([...startingDeckPool(draft.investigator),...Object.keys(slots)])];
  const fields=pool.map(code=>
   `<label>${esc(engine.cards[code]?.name??'Thiếu lá '+code)}
    <input type="number" min="0" max="30" name="${code}" value="${slots[code]??0}" required></label>`).join('');
  editor=`<form id="deck-editor-form">
   <p>${esc(engine.cards[draft.investigator].name)} · ${draft.deck.length}/30 lá thường</p>
   <label>Tên deck <input name="name" maxlength="100" value="${esc(draft.name)}" required></label>
   <div class="deck-counts">${fields}</div>
   <div class="actions">
    <button name="operation" value="save">Lưu deck</button>
    <button name="operation" value="copy">Lưu bản sao</button>
    <button name="operation" value="export">Xuất JSON</button>
    ${engine.s.pending?.kind==='investigator'?'<button class="primary" name="operation" value="play">Chơi deck này</button>':''}
   </div>
  </form>`;
 }
 return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Quản lý deck">
  <h2>Quản lý deck</h2><div class="actions">${entries}<button type="button" data-deck-import>Nhập JSON</button></div>
  ${remoteAvailable?`<form id="remote-deck-form" class="actions">
   <label>Link công khai hoặc ID deck <input name="source" maxlength="256" required></label>
   <button>Nhập từ mạng</button></form>`:''}
  <input hidden type="file" data-deck-file accept=".json,application/json">
  <div class="choices">${saved}</div>
  ${error?`<p role="alert">${esc(error)}</p>`:''}
  ${editor}<div class="actions"><button data-close-inspect>Đóng</button></div>
 </section></div>`;
}

function playableDeckError(cards,draft){
 try{validateStartingDeck(cards,draft.investigator,draft.deck);return '';}
 catch(error){return error.message;}
}


const bondedCardMethods={
 prepareBonded(deck){
  prepareBondedCards(this.s,deck,code=>this.card(code));
 },
 releaseBonded(parent){
  for(const code of Object.keys(this.card(parent).bondedWith??{})){
   const count=this.s.bonded?.[code]??0;
   if(!count)continue;
   this.s.bonded[code]=0;
   this.s.hand.push(code);
   if(count>1){
    this.s.deck.push(...Array(count-1).fill(code));
    this.shuffle(this.s.deck);
   }
   this.log('Bonded: đưa '+count+' lá '+this.card(code).name+' vào tay và deck.','debug');
  }
 },
 reclaimBonded(parent){
  for(const code of Object.keys(this.card(parent).bondedWith??{})){
   for(const zone of ['hand','deck','discard']){
    const before=this.s[zone];
    this.s[zone]=before.filter(card=>card!==code);
    this.addBonded(code,before.length-this.s[zone].length);
   }
  }
 },
 addBonded(code,count){
  if(count>0){
   const bonded=this.s.bonded??={};
   bonded[code]=(bonded[code]??0)+count;
  }
 },
 discardPlayerCard(code){
  const parent=this.card(code).bondedParent;
  if(parent&&!this.asset(parent))this.addBonded(code,1);
  else this.s.discard.push(code);
 },
 melodyTargets(){
  const targets=[{state:this.s,name:this.investigator().name}];
  for(const asset of this.s.assets.filter(asset=>this.card(asset.code).slot==='Ally')){
   targets.push({state:asset,id:asset.id,name:this.card(asset.code).name});
  }
  return targets;
 },
 canPlayMelody(){
  return this.s.deck.length>0||this.s.discard.length>0||
   this.melodyTargets().some(({state})=>state.hp>0||state.horror>0);
 },
 soothingMelody(remaining){
  if(!remaining)return;
  const options=[];
  const targets=this.melodyTargets();
  for(const {state,id,name} of targets)for(const stat of ['hp','horror']){
   if(state[stat]>0)options.push({
    label:name+' · hồi 1 '+(stat==='hp'?'damage':'horror'),
    ops:[{type:'healMelody',stat,id,remaining}]
   });
  }
  if(options.length)this.choice('Soothing Melody: chọn điểm cần hồi.',options);
 },
 healMelody({id,stat,remaining}){
  const target=id?this.s.assets.find(asset=>asset.id===id):this.s;
  if(target?.[stat]>0)target[stat]--;
  this.soothingMelody(remaining-1);
 },
 bloodRiteDiscard(discarded){
  if(discarded>=2||!this.s.hand.length){this.bloodRiteReward(discarded);return;}
  const options=this.s.hand.map((code,index)=>({
   label:'Bỏ '+this.card(code).name,ops:[{type:'bloodRitePay',index,discarded}]
  }));
  options.push({label:'Dừng bỏ bài',ops:[{type:'bloodRiteReward',remaining:discarded}]});
  this.choice('Blood-Rite: bỏ tối đa hai lá.',options);
 },
 bloodRitePay({index,discarded}){
  const [code]=this.s.hand.splice(index,1);
  this.discardPlayerCard(code);
  this.bloodRiteDiscard(discarded+1);
 },
 bloodRiteReward(remaining){
  if(!remaining)return;
  const next={type:'bloodRiteReward',remaining:remaining-1};
  const options=[{label:'Nhận 1 resource',ops:[{type:'resource'},next]}];
  if(this.s.resources>0)for(const enemy of this.s.enemies.filter(e=>e.location===this.s.location)){
   options.push({
    label:'Chi 1 resource · gây 1 damage lên '+this.card(enemy.code).name,
    ops:[{type:'bloodRiteDamage',id:enemy.id},next]
   });
  }
  this.choice('Blood-Rite: chọn hiệu ứng cho lá đã bỏ.',options);
 },
 bloodRiteDamage(id){
  if(this.s.resources<1||!this.s.enemies.some(e=>e.id===id&&e.location===this.s.location))throw Error('Mục tiêu Blood-Rite không hợp lệ.');
  this.s.resources--;
  this.hitEnemy({id,amount:1});
 }
};

const timingRules={
 'when:enemy-attacks':[
  {kind:'reaction',eligible:engine=>(engine.s.hand.includes('01023')||engine.childCanPlay('01023'))&&
   !engine.s.voices&&engine.s.resources>=engine.playCost('01023'),
   title:'Dodge: hủy đòn tấn công này?',
   choices:(engine,event)=>[
    ...(engine.s.hand.includes('01023')?[{label:'Chơi Dodge',ops:[{type:'dodgeAttack',...event}]}]:[]),
    ...(engine.childCanPlay('01023')?[{label:'Boon of the Child · Dodge',ops:[{type:'dodgeAttack',...event,child:true}]}]:[])
   ],
   pass:event=>[{type:'performAttack',...event}]},
  {kind:'reaction',eligible:engine=>engine.s.phase==='enemy',
   title:'Survival Knife: đánh trước khi kẻ địch tấn công?',
   choices:(engine,event)=>engine.s.assets.filter(asset=>asset.code==='53002'&&!asset.exhausted)
    .map(asset=>({label:'Dùng Survival Knife · '+asset.id,
     ops:[{type:'knifeInterrupt',...event,asset:asset.id}]})),
   pass:event=>[{type:'performAttack',...event}]}
 ],
 'after:asset-enters-play':[
  {kind:'forced',eligible:(engine,event)=>Boolean(engine.card(event.code).bondedWith),
   ops:event=>[{type:'releaseBonded',code:event.code}]}
 ],
 'after:enemy-defeated':[
  {kind:'forced',eligible:(_,event)=>event.code==='01180',ops:()=>[{type:'injury',h:1}]},
  {kind:'reaction',eligible:engine=>engine.investigator().code==='01001'&&!engine.s.rolandUsed&&
   engine.here().clues>0&&engine.canSpendClues(0),
   title:'Roland Banks: tìm 1 manh mối sau khi hạ kẻ địch? (1 lần/vòng)',
   label:'Dùng khả năng Roland',ops:()=>[{type:'roland'}],resume:{type:'rolandReaction'}},
  {kind:'reaction',eligible:engine=>(engine.s.hand.includes('01022')||engine.childCanPlay('01022'))&&
   !engine.s.voices&&engine.s.resources>=engine.playCost('01022')&&engine.here().clues>0&&engine.canSpendClues(0),
   title:'Evidence!: tìm 1 manh mối sau khi hạ kẻ địch?',
   choices:engine=>[
    ...(engine.s.hand.includes('01022')?[{label:'Chơi Evidence!',ops:[{type:'evidence'}]}]:[]),
    ...(engine.childCanPlay('01022')?[{label:'Boon of the Child · Evidence!',ops:[{type:'evidence',child:true}]}]:[])
   ],repeat:true}
 ]
};

const timingMethods={
 openTiming(point,event){
  const rules=Object.hasOwn(timingRules,point)?timingRules[point]:null;
  if(!rules)throw Error('Điểm timing không hợp lệ.');
  const forced=rules.filter(rule=>rule.kind==='forced'&&rule.eligible(this,event))
   .flatMap(rule=>rule.ops(event));
  const reactions=rules.filter(rule=>rule.kind==='reaction');
  if(forced.length){
   if(reactions.length){
    const resume=reactions.find(rule=>rule.resume)?.resume;
    forced.push(resume?{...resume}:{type:'timingReactions',point,event});
   }
   this.push(...forced);
   return true;
  }
  return reactions.length>0&&this.timingReactions(point,event);
 },
 timingReactions(point,event){
  const rules=Object.hasOwn(timingRules,point)?timingRules[point]:[];
  const available=rules.filter(rule=>rule.kind==='reaction'&&rule.eligible(this,event)).map(rule=>({
   rule,options:rule.choices?.(this,event)??[{label:rule.label,ops:rule.ops(event)}]
  })).filter(({options})=>options.length);
  if(!available.length)return false;
  const {rule}=available[0];
  const title=available.length===1?rule.title:point==='when:enemy-attacks'?
   'Chọn phản ứng trước khi đòn tấn công xử lý.':'Chọn phản ứng sau khi hạ kẻ địch.';
  const choices=available.flatMap(({rule,options})=>options.map(option=>{
   if(point!=='after:enemy-defeated'||(available.length===1&&!rule.repeat))return option;
   return {...option,ops:[...option.ops,{type:'rolandReaction'}]};
  }));
  this.choice(title,[...choices,{label:'Bỏ qua',ops:rule.pass?.(event)??[]}]);
  return true;
 }
};


